(() => {
  'use strict';
  const KEY='lapka-public-v2', OLD_KEY='lapka-prototype-v1';
  const now=new Date();
  const iso=(d)=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
  const addDays=(date,n)=>{const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return iso(d)};
  const today=iso(now);
  const uid=()=>Math.random().toString(36).slice(2,9);
  const esc=(v='')=>String(v).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const emptyState=()=>({version:2,activePetId:null,pets:[],events:[],foodEntries:[],documents:[],photos:[],settings:{onboardingDone:false,city:'',profileVisible:false,showCity:false,showApprox:false,allowMessages:false},community:{blocked:[],requests:[],reports:[],messages:[]}});
  function loadState(){
    try{const saved=localStorage.getItem(KEY);if(saved)return {...emptyState(),...JSON.parse(saved),version:2,settings:{...emptyState().settings,...JSON.parse(saved).settings},community:{...emptyState().community,...JSON.parse(saved).community}}}catch{}
    try{const raw=localStorage.getItem(OLD_KEY);if(raw){const old=JSON.parse(raw),keepPets=(old.pets||[]).filter(x=>!x.demo),ids=new Set(keepPets.map(x=>x.id)),st=emptyState();st.pets=keepPets;st.activePetId=ids.has(old.activePetId)?old.activePetId:(keepPets[0]?.id||null);st.events=(old.events||[]).filter(x=>!x.demo&&ids.has(x.petId));st.foodEntries=(old.foodEntries||[]).filter(x=>!x.demo&&ids.has(x.petId));st.documents=(old.documents||[]).filter(x=>ids.has(x.petId));st.photos=(old.photos||[]).filter(x=>ids.has(x.petId));st.settings={...st.settings,...old.settings};st.community={...st.community,...old.community,requests:[],blocked:[]};localStorage.setItem(KEY,JSON.stringify(st));localStorage.removeItem(OLD_KEY);return st}}catch{}
    return emptyState();
  }
  let state=loadState();
  if(!Array.isArray(state.pets))state.pets=[];
  if(!state.pets.some(p=>p.id===state.activePetId))state.activePetId=state.pets[0]?.id||null;
  let route='home', subroute='timeline', modal=null, toastTimer=null, foodFilter='all';
  const app=document.getElementById('app'), modalRoot=document.getElementById('modal-root'), toastEl=document.getElementById('toast');
  const fileDB=(()=>{let dbPromise;function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('lapka-local-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}return{put:async(id,blob)=>{const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})},get:async(id)=>{const d=await db();return new Promise((res,rej)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})},del:async(id)=>{const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}}})();
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){notify('Не удалось сохранить изменения. Возможно, закончилось место.');console.error(e)}}
  const petById=id=>state.pets.find(p=>p.id===id);
  const currentPet=()=>petById(state.activePetId)||state.pets[0]||null;
  function petIcon(p,cls='pet-avatar'){if(!p)return `<div class="${cls} pet-photo-frame"><span class="pet-fallback">🐾</span></div>`;return `<div class="${cls} pet-photo-frame">${p.photoId?`<img data-local-file="${esc(p.photoId)}" alt="Фото питомца ${esc(p.name)}"><span class="pet-fallback">${esc(p.emoji||'🐾')}</span>`:`<span class="pet-fallback">${esc(p.emoji||'🐾')}</span>`}</div>`}
  const fmtDate=(s,opts={day:'numeric',month:'long'})=>{if(!s)return 'Дата не указана';const d=new Date(`${s}T12:00:00`);return new Intl.DateTimeFormat('ru-RU',opts).format(d)};
  const dayNum=s=>new Date(`${s}T12:00:00`).getDate();
  function notify(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}
  const navItems=[['home','⌂','Главная'],['pets','🐾','Питомцы'],['care','♡','Забота'],['community','☻','Сообщество'],['more','•••','Ещё']];
  const moreItems=[['places','⌖','Петфрендли места'],['knowledge','▤','База знаний'],['documents','▣','Архив документов'],['gallery','▧','Галерея'],['templates','▤','Шаблоны'],['settings','⚙','Настройки']];
  const routeLabel=()=>({home:'Главная',pets:'Питомцы',care:'Забота',community:'Сообщество',more:'Ещё',places:'Петфрендли места',knowledge:'База знаний',documents:'Архив документов',gallery:'Галерея',templates:'Полезные шаблоны',settings:'Настройки',vet:'Чат с врачом',food:'Проверка продуктов'}[route]||'Лапка');
  function navButton(item, mobile=false){const [id,icon,label]=item;return `<button class="nav-item ${route===id?'active':''}" data-route="${id}" aria-label="${label}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`}
  function shell(content){const desktop=navItems.slice(0,4).map(x=>navButton(x)).join('')+`<div class="nav-label">Уход и сервисы</div>`+[['vet','✚','Чат с врачом'],['food','◉','Опасные продукты'],...moreItems].map(x=>navButton(x)).join('');const mobile=[navItems[0],navItems[1],navItems[2],navItems[3],['more','•••','Ещё']].map(x=>`<button class="${route===x[0]?'active':''}" data-route="${x[0]}" aria-label="${x[2]}"><span class="nav-icon">${x[1]}</span><span>${x[2]}</span></button>`).join('');return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">🐾</div><div><div class="brand-name">Лапка</div><div class="brand-sub">забота рядом</div></div></div><div class="nav-label">Пространство</div><nav class="side-nav">${desktop}</nav><div class="sidebar-bottom"><div class="privacy-mini"><strong>🔒 Личные данные</strong><p>Профили и записи хранятся локально в этом браузере.</p></div><div class="user-mini"><div class="avatar">🐾</div><div><div class="user-name">Мой профиль</div><div class="user-tag">Локальное хранение</div></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Лапка <span style="color:#c4cbc5"> / </span> ${esc(routeLabel())}</div><div class="top-actions"><span class="top-date">${fmtDate(today,{weekday:'short',day:'numeric',month:'long'})}</span>${state.pets.length?`<select class="top-pet-select" id="top-pet-select" aria-label="Выбрать питомца">${state.pets.map(p=>`<option value="${esc(p.id)}" ${p.id===currentPet()?.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<button class="icon-button" data-route="settings" aria-label="Настройки">⚙</button></div></header><div class="content">${content}</div></main><nav class="mobile-nav" aria-label="Основная навигация">${mobile}</nav></div>`}
  function title(eyebrow,h1,sub='',action=''){return `<div class="page-title-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${h1}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}</div>${action}</div>`}
  function demoBanner(text='Локальное хранение: данные остаются в этом браузере. Для синхронизации между устройствами потребуется подключить сервер.'){return `<div class="demo-banner"><span>ⓘ</span><span>${text}</span></div>`}
  function empty(icon,heading,desc,button=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><h3>${heading}</h3><p>${desc}</p>${button}</div>`}
  function quick(icon,tint,label,desc,dest){return `<button class="quick-card" data-route="${dest}"><span class="quick-icon ${tint}">${icon}</span><b>${label}</b><small>${desc}</small></button>`}
  function eventCard(e,compact=false){const p=petById(e.petId);return `<div class="event-row"><div class="event-date"><b>${dayNum(e.date)}</b><small>${fmtDate(e.date,{month:'short'})}</small></div><div class="event-info"><b>${esc(e.title)} ${e.done?'<span class="tag green">Готово</span>':''}</b><p>${esc(p?.name||'Питомец')} · ${esc(e.note||'Без заметки')}${e.repeatDays?` · повтор: ${e.repeatDays} дн.`:''}</p></div><div class="event-actions">${!e.done?`<button class="btn btn-soft btn-small" data-action="event-done" data-id="${e.id}" aria-label="Завершить">✓</button>`:''}<button class="btn btn-secondary btn-small" data-action="edit-event" data-id="${e.id}" aria-label="Изменить">⋯</button></div></div>`}
  function homePage(){const p=currentPet();const upcoming=p?state.events.filter(e=>e.petId===p.id&&!e.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3):[];return `${demoBanner()}<section class="hero"><div class="hero-copy"><div class="eyebrow">Ваше пространство заботы</div><h1>Всё важное<br>о вашем питомце 🐾</h1><p>Профиль, полезные заметки и ежедневный уход — собраны в одном спокойном месте.</p><button class="btn btn-primary" data-route="care">Открыть таймлайн <span>→</span></button></div>${p?`<div class="pet-switcher">${petIcon(p,'pet-emoji')}<div><small>Сейчас выбран</small><select id="hero-pet-select" aria-label="Выбрать питомца">${state.pets.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><button class="btn btn-quiet" data-route="pets" aria-label="Управлять питомцами">↗</button></div>`:`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`}</section><div class="section-heading"><h2>Быстрые действия</h2><span class="tag">${p?`Для ${esc(p.name)}`:'Начните с профиля'}</span></div><div class="quick-grid">${quick('✚','tint-peach','Чат с врачом','Подготовить обращение','vet')}${quick('◉','tint-lav','Опасные продукты','Справочник с источниками','food')}${quick('⌖','tint-blue','Петфрендли места','Каталог мест','places')}${quick('♡','tint-mint','Профиль питомца','Фото и сведения','pets')}${quick('▤','tint-lime','База знаний','Полезные материалы','knowledge')}${quick('▣','tint-peach','Архив документов','Личные файлы','documents')}${quick('◷','tint-blue','Таймлайн','События и напоминания','care')}${quick('♧','tint-lav','Дневник питания','Записи о рационе','care')}${quick('▧','tint-pink','Галерея','Фотографии питомца','gallery')}${quick('✉','tint-lime','Полезные шаблоны','Чек-листы и заметки','templates')}${quick('☻','tint-mint','Сообщество','Без вымышленных профилей','community')}</div><div class="section-heading"><h2>Ближайшие события</h2><button data-route="care">Весь таймлайн →</button></div><div class="card"><div class="event-list">${upcoming.length?upcoming.map(e=>eventCard(e,true)).join(''):empty('◷','Пока нет событий',p?'Создайте напоминание для '+esc(p.name)+'.':'Сначала добавьте питомца, затем создайте напоминание.',p?`<button class="btn btn-primary btn-small" data-action="add-event">Создать событие</button>`:`<button class="btn btn-primary btn-small" data-action="add-pet">Добавить питомца</button>`)}</div></div><p class="footer-note">Приложение помогает вести записи, но не заменяет ветеринарную консультацию.</p>`}
  function petsPage(){return `${title('Профили','Мои питомцы','Создавайте личные карточки, добавляйте фото и переключайтесь между питомцами.',`<button class="btn btn-primary" data-action="add-pet">＋ Добавить питомца</button>`)}${demoBanner('Фотографии и сведения хранятся в текущем браузере. Они не публикуются автоматически.')}${state.pets.length?`<div class="pet-grid">${state.pets.map(p=>`<article class="card pet-card ${p.id===currentPet()?.id?'selected':''}">${petIcon(p,'pet-avatar')}<h3>${esc(p.name)} ${p.id===currentPet()?.id?'<span class="tag green">Выбран</span>':''}</h3><p>${esc(p.species||'Питомец')}${p.breed?` · ${esc(p.breed)}`:''}<br>${p.birthDate?`Дата рождения: ${fmtDate(p.birthDate,{day:'numeric',month:'long',year:'numeric'})}`:'Дата рождения не указана'}</p>${p.note?`<p>${esc(p.note)}</p>`:''}<div class="card-controls"><button class="btn btn-soft btn-small" data-action="select-pet" data-id="${p.id}">Выбрать</button><button class="btn btn-secondary btn-small" data-action="edit-pet" data-id="${p.id}">Изменить</button><button class="btn btn-quiet btn-small" data-action="delete-pet" data-id="${p.id}">Удалить</button></div></article>`).join('')}</div>`:empty('🐾','Профиль питомца появится здесь','Добавьте имя, вид, породу и любимое фото — всё останется приватным.',`<button class="btn btn-primary" data-action="add-pet">Создать профиль питомца</button>`)}`}
  function carePage(){const tab=subroute==='food'?'food':'timeline';const p=currentPet();let body='';if(tab==='timeline'){const list=state.events.filter(e=>!p||e.petId===p.id).sort((a,b)=>a.date.localeCompare(b.date));body=`<div class="section-heading" style="margin-top:0"><h2>События ${p?`· ${esc(p.name)}`:''}</h2><button class="btn btn-primary btn-small" data-action="add-event">＋ Событие</button></div><div class="card"><div class="event-list">${list.length?list.map(e=>eventCard(e)).join(''):empty('◷','Таймлайн пуст','Создайте напоминание или запись о событии.',`<button class="btn btn-primary btn-small" data-action="add-event">Создать событие</button>`)}</div></div><div class="notice">Напоминания — это пользовательские записи, а не медицинские назначения. Интервал обработки и выбор средства обсудите с ветеринаром.</div>`}else{const entries=state.foodEntries.filter(e=>!p||e.petId===p.id).sort((a,b)=>b.date.localeCompare(a.date));body=`<div class="section-heading" style="margin-top:0"><h2>Дневник ${p?`· ${esc(p.name)}`:''}</h2><button class="btn btn-primary btn-small" data-action="add-food">＋ Запись</button></div><div class="grid" style="gap:10px">${entries.length?entries.map(e=>`<div class="list-card"><div class="list-icon">🥣</div><div class="list-main"><b>${esc(e.food)}</b><p>${fmtDate(e.date,{day:'numeric',month:'long',year:'numeric'})} · ${esc(petById(e.petId)?.name||'Питомец')}${e.note?` · ${esc(e.note)}`:''}</p></div><div class="list-actions"><button class="btn btn-secondary btn-small" data-action="edit-food" data-id="${e.id}">Изменить</button><button class="btn btn-quiet btn-small" data-action="delete-food" data-id="${e.id}">Удалить</button></div></div>`).join(''):empty('🥣','Записей пока нет','Добавьте корм или продукт, чтобы вести дневник.')}</div>`}return `${title('Уход и привычки','Забота о питомце','События, напоминания и дневник питания — отдельно для каждого питомца.')}${demoBanner()}<div class="subnav"><button class="${tab==='timeline'?'active':''}" data-sub="timeline">◷ Таймлайн</button><button class="${tab==='food'?'active':''}" data-sub="food">♧ Дневник питания</button></div>${body}`}
  function foodPage(){const count=(window.LAPKA_FOOD_CATALOG||[]).length;return `${title('Проверка продуктов','Можно ли собаке?','Ищите продукт по названию или ингредиенту. У каждой проверенной карточки есть объяснение и источник.')}${demoBanner(`В справочнике ${count} курируемых карточек. Для неизвестного продукта приложение не угадывает и не считает его безопасным.`)}<div class="card"><label class="label" for="food-search">Название продукта</label><form id="food-check-form" class="food-check"><input id="food-search" class="input" placeholder="Например, шоколад, морковь или ксилитол" autocomplete="off"/><button class="btn btn-primary">Найти</button></form><div id="food-result"></div><div class="notice">При возможном поедании опасного продукта, выраженных симптомах или сомнениях немедленно свяжитесь с ветеринарной клиникой. Не ждите ответа справочника и не вызывайте рвоту самостоятельно.</div></div><div class="section-heading"><h2>Справочник</h2><span class="tag">${count} карточек</span></div><div class="subnav food-filters"><button data-food-filter="all" class="${foodFilter==='all'?'active':''}">Все</button><button data-food-filter="danger" class="${foodFilter==='danger'?'active':''}">Опасно</button><button data-food-filter="caution" class="${foodFilter==='caution'?'active':''}">Осторожно</button><button data-food-filter="okay" class="${foodFilter==='okay'?'active':''}">Условно допустимо</button></div><div id="food-catalog-list" class="grid grid-2"></div><p class="footer-note">Справочник не является полной базой токсикологии. Оценка зависит от продукта, состава, количества, размера и здоровья собаки. Обсуждайте рацион с ветеринаром.</p>`}
  function vetPage(){return `${title('Подготовка к консультации','Чат с врачом','Опишите проблему по готовой форме и подготовьте ясное сообщение специалисту.')}${demoBanner('Чат с лицензированным врачом ещё не подключён. Черновик останется у вас и не будет отправлен автоматически.') }<div class="two-col"><section class="card"><div class="profile-hero"><div class="profile-art">🩺</div><div><span class="tag orange">Врач пока не подключён</span><h2 style="font-size:17px;margin-top:8px">Подготовьте обращение заранее</h2><p class="page-subtitle" style="margin-top:5px">Выберите тему и ответьте на вопросы — приложение соберёт короткую сводку для ветеринара.</p></div></div><div class="notice" style="background:#fff2ea;color:#875a3b"><b>Срочно:</b> при затруднённом дыхании, судорогах, потере сознания, сильном кровотечении или резком ухудшении немедленно обращайтесь в круглосуточную клинику. Не ждите ответа в приложении.</div><button class="btn btn-primary" style="margin-top:16px" data-action="open-vet-intake">Подготовить сообщение</button></section><aside class="card"><h2 style="font-size:14px">Что полезно сообщить врачу</h2><div class="grid" style="gap:9px;margin-top:13px"><div class="list-card"><span class="list-icon">1</span><div class="list-main"><b>Когда началось</b><p>Дата, время и изменение симптомов.</p></div></div><div class="list-card"><span class="list-icon">2</span><div class="list-main"><b>Что изменилось</b><p>Аппетит, вода, активность, стул.</p></div></div><div class="list-card"><span class="list-icon">3</span><div class="list-main"><b>Что мог съесть</b><p>Название, количество, время и упаковка.</p></div></div><div class="list-card"><span class="list-icon">4</span><div class="list-main"><b>Лекарства и диагнозы</b><p>Только факты, не назначайте лечение самостоятельно.</p></div></div></div></aside></div>`}

  const VET_TOPICS=['Рвота или диарея','Отказ от еды или воды','Вялость или изменение поведения','Зуд, сыпь или выпадение шерсти','Кашель или чихание','Хромота, боль или травма','Питомец мог съесть опасный продукт','Вакцинация или профилактика','Уход и питание','Другое'];
  function vetIntakeForm(){const p=currentPet();openModal('Подготовить обращение','Заполните только то, что знаете. Это черновик, он не отправляется в клинику.',`<form id="vet-intake-form"><div class="field"><label class="label" for="f-vet-topic">Что беспокоит?</label><select class="select" id="f-vet-topic">${VET_TOPICS.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label class="label" for="f-vet-pet">Питомец</label><select class="select" id="f-vet-pet">${state.pets.length?state.pets.map(x=>`<option value="${x.id}" ${x.id===p?.id?'selected':''}>${esc(x.name)} — ${esc(x.species||'питомец')}</option>`).join(''):'<option value="">Профиль не добавлен</option>'}</select></div><div class="field"><label class="label" for="f-vet-onset">Когда началось?</label><select class="select" id="f-vet-onset"><option>Только что</option><option>Сегодня</option><option>Вчера</option><option>Несколько дней назад</option><option>Не знаю</option></select></div><div class="field"><label class="label" for="f-vet-symptoms">Что вы наблюдаете?</label><textarea class="textarea" id="f-vet-symptoms" placeholder="Например: сколько раз, как менялось состояние, что отличается от обычного"></textarea></div><div class="field"><label class="label" for="f-vet-ingestion">Мог ли питомец что-то съесть или лизнуть?</label><textarea class="textarea" id="f-vet-ingestion" placeholder="Название, примерное количество и время; упаковку сохраните"></textarea></div><div class="field"><label class="label" for="f-vet-meds">Лекарства, аллергии и известные заболевания</label><textarea class="textarea" id="f-vet-meds" placeholder="Укажите препараты и дозы, если известны. Не начинайте лечение по этой форме."></textarea></div><label class="check-row urgency-check"><input type="checkbox" id="f-vet-urgent"> Есть затруднённое дыхание, судороги, потеря сознания, сильное кровотечение или быстрое ухудшение.</label><div class="notice" id="vet-urgent-note" hidden><b>Не ждите переписки.</b> Немедленно позвоните в круглосуточную ветеринарную клинику или езжайте туда.</div><button type="button" class="btn btn-primary" style="margin-top:15px" data-action="make-vet-summary">Собрать сообщение</button><div id="vet-summary-box" hidden style="margin-top:16px"><label class="label" for="vet-summary-text">Черновик для ветеринара</label><textarea class="textarea vet-summary" id="vet-summary-text" readonly></textarea><div class="help">Проверьте текст перед отправкой. Никакие данные автоматически не передаются.</div><button type="button" class="btn btn-soft btn-small" style="margin-top:9px" data-action="copy-vet-summary">Копировать текст</button></div></form>`,{wide:true})}
  function buildVetSummary(){const pet=petById(document.getElementById('f-vet-pet')?.value),topic=document.getElementById('f-vet-topic')?.value||'Вопрос',onset=document.getElementById('f-vet-onset')?.value||'Не указано',symptoms=document.getElementById('f-vet-symptoms')?.value.trim()||'Пока не описаны',ingestion=document.getElementById('f-vet-ingestion')?.value.trim()||'Не знаю / не относится',meds=document.getElementById('f-vet-meds')?.value.trim()||'Не указано';return `Здравствуйте. Нужна консультация по питомцу${pet?` ${pet.name} (${pet.species||'вид не указан'}${pet.breed?`, ${pet.breed}`:''})`:''}.\n\nЧто беспокоит: ${topic}.\nКогда началось: ${onset}.\nНаблюдения: ${symptoms}.\nЧто мог съесть/лизнуть: ${ingestion}.\nЛекарства, аллергии, заболевания: ${meds}.\n\nПодскажите, пожалуйста, какие сведения ещё нужны и как лучше организовать осмотр.\n\nСообщение подготовлено владельцем; диагноз и лечение не предполагаются.`}
  function communityPage(){const settings=state.settings;return `${title('Знакомства и прогулки','Сообщество','Здесь будут реальные участники — только после запуска сервера и их согласия.')}${demoBanner('Вымышленных пользователей нет. Сейчас общий поиск и личные сообщения не подключены; ничего не публикуется.') }<div class="two-col"><section><div class="card"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><div><h2 style="font-size:15px">Видимость моего профиля</h2><p class="page-subtitle" style="margin-top:6px">Настройка сохраняется локально и не делает профиль публичным без сервера.</p></div><input class="switch" type="checkbox" data-setting="profileVisible" ${settings.profileVisible?'checked':''} aria-label="Показывать мой профиль в поиске"></div><div class="notice">Точные координаты, домашний адрес и маршруты не отображаются. Публичного списка участников сейчас нет.</div><button class="btn btn-secondary btn-small" style="margin-top:12px" data-route="settings">Настроить приватность</button></div><div class="section-heading"><h2>Участники</h2><span class="tag">Без фиктивных аккаунтов</span></div><div class="card">${empty('☻','Пока нет подключённых участников','Мы не показываем вымышленные карточки. Чтобы здесь появились владельцы, нужен публичный сервер с аккаунтами, модерацией и настройками согласия.')}</div></section><aside><div class="card"><h2 style="font-size:14px">Безопасное знакомство</h2><div class="notice">Не публикуйте домашний адрес, номер телефона, документы и расписание прогулок. Для первой встречи выбирайте общественное место.</div><hr class="hr"><button class="btn btn-secondary btn-small" data-action="community-rules">Правила сообщества</button><p class="footer-note">Личные сообщения, блокировка и жалобы должны проверяться на сервере до публичного запуска.</p></div></aside></div>`}
  function placesPage(){return `${title('Гулять вместе','Петфрендли места','Подключённого каталога заведений пока нет.')}${demoBanner('Мы не добавляем вымышленные адреса или режим работы. Поиск начнёт показывать места после подключения проверяемого источника.') }<div class="card">${empty('⌖','Каталог пока не подключён','Реальные точки, часы работы и доступность должны загружаться из проверенного сервиса. Геолокация выключена по умолчанию.')}</div>`}
  const articles=[['✂️','Бережный груминг','Как подготовить питомца к спокойному уходу.','Материал-черновик · нужна проверка специалистом'],['👁️','Уход за глазами','Общие вопросы гигиены и когда стоит обратиться к врачу.','Справочная карточка · не медицинская рекомендация'],['🧰','Аптечка питомца','Шаблон списка для обсуждения с ветеринаром.','Материал-черновик · не инструкция по лечению'],['🚶','Прогулки','Идеи для безопасных и комфортных прогулок.','Общие заметки · требуется редактура'],['🐕','Акита-ину','Краткая карточка породы. Индивидуальные особенности различаются.','Источники не подключены · черновик'],['🐕‍🦺','Алабай','Краткая карточка породы. Индивидуальные особенности различаются.','Источники не подключены · черновик']];
  function knowledgePage(){return `${title('Полезное рядом','База знаний','Карточки для чтения. Содержимое требует фактчекинга и ветеринарной редакции.')}${demoBanner('Статьи — черновики, не являются медицинскими рекомендациями. Проверенные источники и даты обновления не подключены.') }<div class="filter-row"><div class="searchbar"><span>⌕</span><input id="knowledge-search" placeholder="Найти статью" /></div><span class="tag">6 черновиков материалов</span></div><div class="grid grid-3" id="knowledge-grid">${articles.map((a,i)=>`<article class="card article-card knowledge-item" data-index="${i}" data-search="${esc(a[1].toLowerCase())}"><div class="article-art">${a[0]}</div><h3>${a[1]}</h3><p>${a[2]}</p><div class="article-meta">${a[3]}</div></article>`).join('')}</div>`}
  function documentsPage(){const items=state.documents.filter(d=>!currentPet()||d.petId===currentPet().id);return `${title('Личное хранилище','Архив документов','Файлы остаются в IndexedDB этого браузера и никуда не загружаются.',`<button class="btn btn-primary" data-action="add-document">＋ Добавить файл</button>`)}${demoBanner('Локальное хранилище не является резервной копией. При очистке данных браузера файлы могут быть удалены.') }<div class="grid" style="gap:10px">${items.length?items.map(d=>`<div class="list-card"><div class="list-icon">▣</div><div class="list-main"><b>${esc(d.name)}</b><p>${esc(petById(d.petId)?.name||'Питомец')} · ${fmtDate(d.date,{day:'numeric',month:'long',year:'numeric'})} · ${esc(d.kind||'Документ')} · ${Math.max(1,Math.round((d.size||0)/1024))} КБ</p></div><div class="list-actions"><button class="btn btn-soft btn-small" data-action="download-file" data-id="${d.fileId}" data-name="${esc(d.name)}">Открыть</button><button class="btn btn-quiet btn-small" data-action="delete-document" data-id="${d.id}" data-file="${d.fileId}">Удалить</button></div></div>`).join(''):empty('▣','Архив пуст','Добавьте документ, чтобы хранить его в этом браузере.',`<button class="btn btn-primary btn-small" data-action="add-document">Добавить файл</button>`)}</div>`}
  function galleryPage(){const items=state.photos.filter(d=>!currentPet()||d.petId===currentPet().id);return `${title('Тёплые моменты','Галерея','Приватные фотографии выбранного питомца, сохранённые локально.',`<button class="btn btn-primary" data-action="add-photo">＋ Добавить фото</button>`)}${demoBanner('Фото доступны только в текущем браузере и не публикуются в сообществе.') }${items.length?`<div class="photo-grid">${items.map(x=>`<div class="photo-tile"><img data-local-file="${x.fileId}" alt="${esc(x.name)}"><span class="photo-fallback">🐾</span><button class="btn btn-danger btn-small" data-action="delete-photo" data-id="${x.id}" data-file="${x.fileId}" aria-label="Удалить фото">×</button></div>`).join('')}</div>`:empty('▧','Здесь появятся фотографии','Добавьте снимок, чтобы собрать приватную галерею.',`<button class="btn btn-primary btn-small" data-action="add-photo">Добавить фото</button>`)}`}
  function templatesPage(){const ts=[['🩺','Подготовка к визиту к ветеринару','Запишите вопросы и наблюдения для обсуждения со специалистом.','Вопросы · даты · заметки'],['🧳','Список для поездки','Проверьте документы и привычные вещи питомца перед дорогой.','Документы · корм · контакты клиники'],['🐾','Знакомство на прогулке','Небольшой план, чтобы договориться о безопасной встрече.','Общественное место · время · пожелания'],['📝','Профиль питомца','Соберите основные сведения о питомце в одном месте.','Имя · особенности · контакты владельца (приватно)']];return `${title('Готовые заготовки','Полезные шаблоны','Небольшие списки, которые можно заполнить под себя.')}${demoBanner('Шаблоны — вспомогательные заметки. Медицинские решения принимайте вместе с ветеринаром.') }<div class="grid grid-2">${ts.map((t,i)=>`<article class="card article-card template-item" data-template="${i}"><div class="list-icon" style="margin-bottom:14px">${t[0]}</div><h3>${t[1]}</h3><p style="font-size:11px;color:var(--muted);line-height:1.6">${t[2]}</p><div class="article-meta">Поля: ${t[3]}</div><button class="btn btn-soft btn-small" style="margin-top:13px" data-action="open-template" data-id="${i}">Открыть шаблон</button></article>`).join('')}</div>`}
  function settingsPage(){const s=state.settings;return `${title('Ваш контроль','Настройки приватности','Профиль, геолокация и данные по умолчанию остаются приватными.')}${demoBanner('Настройки ниже показывают локальное поведение прототипа; серверной публикации не происходит.') }<div class="two-col"><div class="card"><h2 style="font-size:15px;margin-bottom:5px">Обнаружение в сообществе</h2><p class="page-subtitle" style="margin:0 0 8px">Публичный поиск отключён, пока вы явно не включите его.</p>${[['profileVisible','Показывать мой профиль в поиске','Только выбранные публичные сведения.'],['showCity','Показывать город/регион','Точная геолокация не отображается.'],['showApprox','Показывать примерную близость','Расстояние не выдаётся как точная координата.'],['allowMessages','Разрешить запросы на общение','Сообщения появятся после подключения защищённого серверного чата.']].map(x=>`<div class="switch-row"><div><b>${x[1]}</b><p>${x[2]}</p></div><input class="switch" type="checkbox" data-setting="${x[0]}" ${s[x[0]]?'checked':''} aria-label="${x[1]}"></div>`).join('')}<div class="field" style="margin-top:16px"><label class="label" for="manual-city">Город (вводится вручную)</label><input class="input" id="manual-city" value="${esc(s.city||'')}" placeholder="Необязательно" /><div class="help">Необязательно. Не сохраняем точку GPS и историю перемещений.</div><button class="btn btn-secondary btn-small" style="margin-top:8px" data-action="save-city">Сохранить город</button></div><button class="btn btn-secondary btn-small" data-action="request-location">Запросить геолокацию</button></div><div class="card"><h2 style="font-size:15px">Данные на устройстве</h2><p class="page-subtitle">Экспортируйте локальные записи или удалите локальные данные.</p><div class="grid" style="margin-top:18px"><button class="btn btn-soft" data-action="export-data">↓ Экспортировать данные JSON</button><button class="btn btn-secondary" data-action="reset-data">Сбросить приложение</button></div><div class="notice">Аккаунт, сервер и синхронизация пока не подключены. Удаление данных браузера может удалить файлы.</div><hr class="hr"><h3 style="font-size:12px">Безопасность встреч</h3><p class="page-subtitle">Не сообщайте домашний адрес и выбирайте общественное место для первой встречи.</p><button class="btn btn-secondary btn-small" data-action="community-rules">Правила сообщества</button></div></div>`}
  function morePage(){return `${title('Разделы','Всё для питомца','Библиотека, файлы и настройки в одном месте.')}<div class="quick-grid">${quick('⌖','tint-blue','Петфрендли места','Каталог мест','places')}${quick('▤','tint-lime','База знаний','Черновики статей','knowledge')}${quick('▣','tint-peach','Архив документов','Локальное хранение','documents')}${quick('▧','tint-pink','Галерея','Локальные фото','gallery')}${quick('✉','tint-lav','Полезные шаблоны','Чек-листы','templates')}${quick('⚙','tint-mint','Настройки','Приватность и данные','settings')}${quick('✚','tint-peach','Чат с врачом','Не подключён','vet')}${quick('◉','tint-lav','Опасные продукты','Справочник продуктов','food')}</div>`}
  function render(){let content='';switch(route){case'home':content=homePage();break;case'pets':content=petsPage();break;case'care':content=carePage();break;case'food':content=foodPage();break;case'vet':content=vetPage();break;case'community':content=communityPage();break;case'places':content=placesPage();break;case'knowledge':content=knowledgePage();break;case'documents':content=documentsPage();break;case'gallery':content=galleryPage();break;case'templates':content=templatesPage();break;case'settings':content=settingsPage();break;default:content=morePage();route='more'}app.innerHTML=shell(content);renderModal();hydrateImages();if(route==='food')renderFoodCatalog('');}
  async function hydrateImages(){document.querySelectorAll('img[data-local-file]').forEach(async img=>{try{const b=await fileDB.get(img.dataset.localFile);if(b){const url=URL.createObjectURL(b);img.src=url;img.onload=()=>img.parentElement.querySelector('.photo-fallback,.pet-fallback')?.remove()}}catch{}})}
  function openModal(titleText,desc,body,opts={}){modal={title:titleText,desc,body,wide:!!opts.wide,footer:opts.footer||''};renderModal();hydrateImages();setTimeout(()=>modalRoot.querySelector('input,select,textarea,button')?.focus(),30)}
  function closeModal(){modal=null;renderModal()}
  function renderModal(){if(!modal){modalRoot.innerHTML='';return}modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${modal.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${esc(modal.title)}</h2>${modal.desc?`<p>${esc(modal.desc)}</p>`:''}</div><button class="close-btn" data-action="close-modal" aria-label="Закрыть">×</button></div>${modal.body}${modal.footer?`<div class="modal-footer">${modal.footer}</div>`:''}</section></div>`}
  const field=(label,name,value='',type='text',placeholder='')=>`<div class="field"><label class="label" for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value||'')}" placeholder="${placeholder}" /></div>`;
  const selectField=(label,name,value,options)=>`<div class="field"><label class="label" for="f-${name}">${label}</label><select class="select" id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
  const textField=(label,name,value='',placeholder='')=>`<div class="field"><label class="label" for="f-${name}">${label}</label><textarea class="textarea" id="f-${name}" name="${name}" placeholder="${placeholder}">${esc(value||'')}</textarea></div>`;
  function petForm(p=null){const edit=!!p;openModal(edit?'Профиль питомца':'Новый профиль питомца',edit?'Обновите фото или сведения питомца.':'Добавьте питомца и выберите его фото профиля.',`<form id="pet-form">${field('Имя питомца *','name',p?.name||'','text','Например, Рада')}<div class="form-row">${selectField('Вид','species',p?.species||'Собака',['Собака','Кошка','Другое'])}${field('Порода','breed',p?.breed||'','text','Если знаете')}</div><div class="form-row">${field('Дата рождения','birthDate',p?.birthDate||'','date')}${selectField('Значок','emoji',p?.emoji||'🐕',['🐕','🐈','🐇','🐾','🦜','🐢'])}</div><div class="field"><span class="label">Фото профиля питомца</span><div id="pet-photo-preview">${petIcon(p,'pet-avatar profile-pet-avatar')}</div><label class="label" for="f-photo">Загрузить фото</label><input class="input" type="file" id="f-photo" accept="image/*"/><div class="help">JPG, PNG или WebP, до 10 МБ. Фото хранится в этом браузере и не публикуется автоматически.</div>${p?.photoId?`<button type="button" class="btn btn-quiet btn-small" data-action="remove-pet-photo">Убрать фото</button>`:''}</div>${textField('Заметка','note',p?.note||'','Особенности, которые важно помнить')}<input type="hidden" name="id" value="${p?.id||''}"/><input type="hidden" name="currentPhotoId" id="current-photo-id" value="${esc(p?.photoId||'')}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">${edit?'Сохранить профиль':'Создать профиль'}</button></div></form>`);hydrateImages()}
  function eventForm(e=null){if(!state.pets.length){notify('Сначала добавьте питомца');return}const edit=!!e,p=currentPet();openModal(edit?'Изменить событие':'Новое событие',`Для питомца: ${p?.name||'не выбран'}. Содержание вводит владелец.`, `<form id="event-form">${field('Название *','title',e?.title||'','text','Например, визит к ветеринару')}${field('Дата *','date',e?.date||today,'date')}<div class="field"><label class="label" for="f-petName">Питомец</label><select class="select" name="petId" id="f-petName">${state.pets.map(x=>`<option value="${x.id}" ${(e?.petId||p?.id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${textField('Пояснение','note',e?.note||'','Добавьте заметку')}<div class="field"><label class="label" for="f-repeat">Повтор</label><select class="select" id="f-repeat" name="repeatDays"><option value="0" ${!e?.repeatDays?'selected':''}>Без повтора</option><option value="7" ${e?.repeatDays===7?'selected':''}>Каждую неделю</option><option value="30" ${e?.repeatDays===30?'selected':''}>Каждые 30 дней</option><option value="90" ${e?.repeatDays===90?'selected':''}>Каждые 90 дней</option></select><div class="help">Повтор — только напоминание. Медицинский график обсудите с ветеринаром.</div></div><input type="hidden" name="id" value="${e?.id||''}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить событие</button></div></form>`)}
  function foodForm(e=null){if(!state.pets.length){notify('Сначала добавьте питомца');return}const p=currentPet();openModal(e?'Изменить запись':'Запись питания',`Дневник ${p?.name||'питомца'}.`, `<form id="food-form">${field('Продукт или корм *','food',e?.food||'','text','Название корма или продукта')}${field('Дата *','date',e?.date||today,'date')}<div class="field"><label class="label" for="f-foodpet">Питомец</label><select class="select" id="f-foodpet" name="petId">${state.pets.map(x=>`<option value="${x.id}" ${(e?.petId||p?.id)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${textField('Заметка','note',e?.note||'','Например, самочувствие после кормления')}<input type="hidden" name="id" value="${e?.id||''}"/><div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`)}
  function fileForm(kind){if(!state.pets.length){notify('Сначала добавьте питомца');return}const isPhoto=kind==='photo';openModal(isPhoto?'Добавить фото':'Добавить документ',`Файл будет сохранён только в текущем браузере.`, `<form id="file-form" data-kind="${kind}"><div class="field"><label class="label" for="f-file">${isPhoto?'Фотография':'Файл'}</label><input class="input" id="f-file" type="file" ${isPhoto?'accept="image/*"':''} required /><div class="help">${isPhoto?'Поддерживаются изображения.':'Не загружайте конфиденциальные документы на чужих устройствах.'}</div></div><div class="field"><label class="label" for="f-filepet">Питомец</label><select class="select" id="f-filepet">${state.pets.map(x=>`<option value="${x.id}" ${x.id===currentPet()?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${!isPhoto?`<div class="field"><label class="label" for="f-kind">Тип документа</label><select class="select" id="f-kind"><option>Ветеринарный документ</option><option>Анализы</option><option>Страховка</option><option>Другое</option></select></div>`:''}<div class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-primary">Сохранить локально</button></div></form>`)}
  const FOOD_STATUS={danger:{title:'Опасно',icon:'!',className:'danger'},caution:{title:'Осторожно',icon:'⚠',className:'caution'},okay:{title:'Условно допустимо',icon:'✓',className:'okay'},unknown:{title:'Не оценено',icon:'?',className:'unknown'}};
  const normFood=s=>String(s||'').toLocaleLowerCase('ru').replace(/ё/g,'е').normalize('NFKC').replace(/[^a-zа-я0-9]+/gi,' ').trim();
  function matchFood(raw){const q=normFood(raw);if(!q)return null;const all=window.LAPKA_FOOD_CATALOG||[];const entries=all.flatMap(item=>[item.name,...item.aliases].map(alias=>({item,alias:normFood(alias)}))).sort((a,b)=>b.alias.length-a.alias.length);return entries.find(x=>q===x.alias||(` ${q} `).includes(` ${x.alias} `))?.item||null}
  function foodSource(item){const source=window.LAPKA_FOOD_SOURCES?.[item.source];return source?`<div class="food-source">Источник: <a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.name)}</a> · проверено ${esc(source.checked)}</div>`:`<div class="food-source">Источник не подтверждён</div>`}
  function foodCard(item){const st=FOOD_STATUS[item.status]||FOOD_STATUS.unknown;return `<article class="card food-card"><div class="food-card-top"><h3>${esc(item.name)}</h3><span class="food-status ${st.className}">${st.icon} ${st.title}</span></div><p>${esc(item.why)}</p><div class="help"><b>Что учесть:</b> ${esc(item.how)}</div>${foodSource(item)}</article>`}
  function showFoodResult(raw){const box=document.getElementById('food-result');if(!box)return;const query=String(raw||'').trim();if(!query){box.innerHTML='';return}const item=matchFood(query);if(item){const st=FOOD_STATUS[item.status]||FOOD_STATUS.unknown;box.innerHTML=`<div class="result-box ${st.className}"><div class="result-title"><span class="badge">${st.icon}</span><span>${st.title}: ${esc(item.name)}</span></div><p>${esc(item.why)}</p><p><b>Что делать:</b> ${esc(item.how)}</p>${foodSource(item)}</div>`;return}const q=normFood(query),all=window.LAPKA_FOOD_CATALOG||[],suggestions=all.filter(x=>[x.name,...x.aliases].some(a=>normFood(a).includes(q)||q.includes(normFood(a)))).slice(0,4);box.innerHTML=`<div class="result-box safe"><div class="result-title"><span class="badge" style="background:#e8eee7">?</span><span>«${esc(query)}» не найдено</span></div><p>В проверяемом справочнике нет точной карточки. Это не означает, что продукт безопасен: не давайте его, пока не проверите состав и не уточните у ветеринара.</p>${suggestions.length?`<div class="help"><b>Возможно, вы имели в виду:</b> ${suggestions.map(x=>`<button class="btn btn-secondary btn-small" type="button" data-food-suggest="${esc(x.id)}">${esc(x.name)}</button>`).join(' ')}</div>`:''}</div>`}
  function renderFoodCatalog(query=''){const host=document.getElementById('food-catalog-list');if(!host)return;const all=window.LAPKA_FOOD_CATALOG||[],q=normFood(query);let list=all.filter(x=>foodFilter==='all'||x.status===foodFilter);if(q)list=list.filter(x=>[x.name,...x.aliases].some(a=>normFood(a).includes(q)));host.innerHTML=list.length?list.map(foodCard).join(''):empty('⌕','Ничего не найдено','Попробуйте другое название. Если продукта нет в базе, статус остаётся неизвестным.');document.querySelectorAll('[data-food-filter]').forEach(b=>b.classList.toggle('active',b.dataset.foodFilter===foodFilter))}
  function go(routeName){route=routeName;render();window.scrollTo({top:0,behavior:'smooth'})}
  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name||'файл';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
  function confirmBox(titleText,desc,onYes,label='Удалить'){openModal(titleText,desc,`<div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal">Отмена</button><button class="btn btn-danger" data-action="confirm-action">${label}</button></div>`);document.querySelector('[data-action="confirm-action"]')?.addEventListener('click',()=>{closeModal();onYes()},{once:true})}
  document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route]');if(nav){go(nav.dataset.route);return}const sub=e.target.closest('[data-sub]');if(sub){subroute=sub.dataset.sub;go('care');return}const ex=e.target.closest('[data-food-example]');if(ex){go('food');setTimeout(()=>{const inp=document.getElementById('food-search');if(inp){inp.value=ex.dataset.foodExample;showFoodResult(inp.value)}},10);return}const foodFilterButton=e.target.closest('[data-food-filter]');if(foodFilterButton){foodFilter=foodFilterButton.dataset.foodFilter;renderFoodCatalog(document.getElementById('food-search')?.value||'');return}const foodSuggest=e.target.closest('[data-food-suggest]');if(foodSuggest){const item=(window.LAPKA_FOOD_CATALOG||[]).find(x=>x.id===foodSuggest.dataset.foodSuggest);if(item){const input=document.getElementById('food-search');if(input){input.value=item.name;showFoodResult(item.name);renderFoodCatalog(item.name)}}return}const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;switch(act){case'close-modal':closeModal();break;case'backdrop':if(e.target===b)closeModal();break;case'add-pet':petForm();break;case'edit-pet':petForm(petById(id));break;case'remove-pet-photo':{const hidden=document.getElementById('current-photo-id');if(hidden)hidden.value='';const box=document.getElementById('pet-photo-preview');if(box)box.innerHTML=`<div class="pet-avatar pet-photo-frame profile-pet-avatar"><span class="pet-fallback">🐾</span></div>`;b.remove();break}case'delete-pet':{const p=petById(id);confirmBox('Удалить профиль питомца?',`Профиль «${p?.name||''}» и связанные с ним записи, файлы и события будут удалены.`,async()=>{const fileItems=[...state.documents,...state.photos].filter(x=>x.petId===id);for(const x of fileItems)try{await fileDB.del(x.fileId)}catch{}if(p?.photoId)try{await fileDB.del(p.photoId)}catch{}state.pets=state.pets.filter(x=>x.id!==id);state.events=state.events.filter(x=>x.petId!==id);state.foodEntries=state.foodEntries.filter(x=>x.petId!==id);state.documents=state.documents.filter(x=>x.petId!==id);state.photos=state.photos.filter(x=>x.petId!==id);state.activePetId=state.pets[0]?.id||null;save();render();notify('Профиль удалён')});break}case'select-pet':state.activePetId=id;save();render();notify('Питомец выбран');break;case'add-event':eventForm();break;case'edit-event':eventForm(state.events.find(x=>x.id===id));break;case'event-done':{const ev=state.events.find(x=>x.id===id);if(ev){ev.done=true;if(ev.repeatDays){state.events.push({...ev,id:uid(),date:addDays(ev.date,Number(ev.repeatDays)),done:false,demo:false})}save();render();notify(ev.repeatDays?'Событие завершено, создан следующий повтор':'Событие отмечено как выполненное')}break}case'add-food':foodForm();break;case'edit-food':foodForm(state.foodEntries.find(x=>x.id===id));break;case'delete-food':confirmBox('Удалить запись?', 'Запись дневника будет удалена.',()=>{state.foodEntries=state.foodEntries.filter(x=>x.id!==id);save();render()});break;case'add-document':fileForm('document');break;case'add-photo':fileForm('photo');break;case'delete-document':case'delete-photo':confirmBox('Удалить файл?','Файл будет удалён из локального хранилища.',async()=>{try{await fileDB.del(b.dataset.file)}catch{}if(act==='delete-document')state.documents=state.documents.filter(x=>x.id!==id);else state.photos=state.photos.filter(x=>x.id!==id);save();render();notify('Файл удалён')});break;case'download-file':try{const blob=await fileDB.get(id);if(blob)downloadBlob(blob,b.dataset.name);else notify('Файл не найден в хранилище')}catch{notify('Не удалось открыть локальный файл')}break;case'open-vet-intake':vetIntakeForm();break;case'make-vet-summary':{const urgent=document.getElementById('f-vet-urgent')?.checked,notice=document.getElementById('vet-urgent-note'),box=document.getElementById('vet-summary-box'),area=document.getElementById('vet-summary-text');if(notice)notice.hidden=!urgent;if(box)box.hidden=false;if(area)area.value=buildVetSummary();break}case'copy-vet-summary':{const area=document.getElementById('vet-summary-text');if(area){area.focus();area.select();try{await navigator.clipboard.writeText(area.value);notify('Черновик скопирован')}catch{document.execCommand('copy');notify('Черновик выделен — скопируйте его')}}break}case'open-template':openTemplate(Number(id));break;case'save-city':{const city=document.getElementById('manual-city')?.value.trim()||'';state.settings.city=city;save();notify(city?'Город сохранён локально':'Город очищен');break}case'request-location':requestLocation();break;case'export-data':exportData();break;case'reset-data':confirmBox('Сбросить все данные?','Локальные профили, записи и настройки будут удалены. Файлы в IndexedDB тоже будут очищены.',async()=>{try{const d=await indexedDB.open('lapka-local-files',1);d.onsuccess=()=>{const tx=d.result.transaction('files','readwrite');tx.objectStore('files').clear()}}catch{}localStorage.removeItem(KEY);state=emptyState();save();go('home');intro();notify('Локальные данные удалены')},'Сбросить');break;case'community-rules':openModal('Правила сообщества','Общие функции появятся после подключения сервера.',`<div class="notice">Не публикуйте точный адрес, телефон, личную почту, документы и сведения о расписании прогулок. Не отправляйте деньги незнакомым людям. Для первой встречи выбирайте общественное место, сообщите близкому человеку о планах. Пожаловаться и заблокировать пользователя можно будет после запуска серверной версии.</div><div class="modal-footer"><button class="btn btn-primary" data-action="close-modal">Понятно</button></div>`);break;default:break}});
  document.addEventListener('change',e=>{if(e.target.id==='f-photo'){const file=e.target.files?.[0];if(file&&file.type.startsWith('image/')){const box=document.getElementById('pet-photo-preview');if(box){const url=URL.createObjectURL(file);box.innerHTML=`<div class="pet-avatar pet-photo-frame profile-pet-avatar"><img src="${url}" alt="Предпросмотр фото питомца"></div>`}}}if(e.target.matches('#top-pet-select,#hero-pet-select')){state.activePetId=e.target.value;save();render()}if(e.target.matches('[data-setting]')){state.settings[e.target.dataset.setting]=e.target.checked;save();notify('Настройка сохранена локально')}});
  document.addEventListener('input',e=>{if(e.target.id==='food-search'){showFoodResult(e.target.value);renderFoodCatalog(e.target.value);}if(e.target.id==='knowledge-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.knowledge-item').forEach(x=>x.hidden=!x.dataset.search.includes(q))}if(e.target.id==='place-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.place-item').forEach(x=>x.hidden=!x.dataset.search.includes(q))}});
  document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;const data=new FormData(f);const formId=f.getAttribute('id');if(formId==='pet-form'){const name=String(data.get('name')||'').trim();if(!name){notify('Укажите имя питомца');return}const id=String(data.get('id')||''),old=petById(id),file=document.getElementById('f-photo')?.files?.[0];if(file&&(!file.type.startsWith('image/')||file.size>10*1024*1024)){notify('Выберите изображение до 10 МБ');return}let photoId=String(data.get('currentPhotoId')||'');if(file){photoId=uid();try{await fileDB.put(photoId,file)}catch{notify('Не удалось сохранить фото в браузере');return}}const obj={id:id||uid(),name,species:data.get('species'),breed:String(data.get('breed')||'').trim(),birthDate:data.get('birthDate')||'',note:String(data.get('note')||'').trim(),emoji:data.get('emoji')||'🐾',photoId};if(id)state.pets=state.pets.map(x=>x.id===id?{...x,...obj}:x);else{state.pets.push(obj);state.activePetId=obj.id}if(old?.photoId&&old.photoId!==photoId)try{await fileDB.del(old.photoId)}catch{}save();closeModal();render();notify(id?'Профиль обновлён':'Профиль питомца создан')}
    else if(formId==='event-form'){const title=String(data.get('title')||'').trim(),date=data.get('date');if(!title||!date){notify('Заполните название и дату');return}const id=String(data.get('id')||'');const obj={id:id||uid(),petId:data.get('petId'),title,date,note:String(data.get('note')||'').trim(),repeatDays:Number(data.get('repeatDays')||0),done:false,demo:false};if(id)state.events=state.events.map(x=>x.id===id?{...x,...obj}:x);else state.events.push(obj);save();closeModal();render();notify(id?'Событие обновлено':'Событие добавлено')}
    else if(formId==='food-form'){const food=String(data.get('food')||'').trim(),date=data.get('date');if(!food||!date){notify('Укажите продукт и дату');return}const id=String(data.get('id')||'');const obj={id:id||uid(),petId:data.get('petId'),food,date,note:String(data.get('note')||'').trim(),demo:false};if(id)state.foodEntries=state.foodEntries.map(x=>x.id===id?{...x,...obj}:x);else state.foodEntries.unshift(obj);save();closeModal();render();notify(id?'Запись обновлена':'Запись добавлена')}
    else if(f.id==='file-form'){const file=document.getElementById('f-file').files[0];if(!file){notify('Выберите файл');return}if(file.size>20*1024*1024){notify('Максимальный размер файла — 20 МБ');return}const fileId=uid();try{await fileDB.put(fileId,file);const kind=f.dataset.kind;const obj={id:uid(),fileId,name:file.name,size:file.size,date:today,petId:document.getElementById('f-filepet').value,kind:document.getElementById('f-kind')?.value||'',mime:file.type};if(kind==='photo')state.photos.unshift(obj);else state.documents.unshift(obj);save();closeModal();render();notify('Файл сохранён локально')}catch(err){console.error(err);notify('Не удалось сохранить файл в браузере')}}
  });
  function openTemplate(i){const t=[['Подготовка к визиту к ветеринару','Соберите наблюдения и вопросы, которые хотите обсудить со специалистом.','Дата визита · вопросы · наблюдения · документы'],['Список для поездки','Проверьте привычные вещи и документы перед поездкой.','Документы · корм · вещи · контакт клиники'],['Знакомство на прогулке','Согласуйте безопасную встречу в общественном месте.','Время · общественное место · пожелания'],['Профиль питомца','Соберите основные сведения о питомце.','Имя · порода · особенности · заметки']][i];if(!t)return;openModal(t[0],t[1],`<div class="notice">Поля: ${esc(t[2])}</div><form id="template-form">${textField('Моя заметка','template-note','','Заполните здесь свои пункты')}<div class="modal-footer"><button class="btn btn-secondary" type="button" data-action="close-modal">Закрыть</button><button class="btn btn-primary">Сохранить в заметки</button></div></form>`)}
  function requestLocation(){if(!navigator.geolocation){notify('Геолокация недоступна. Город можно указать вручную.');return}openModal('Зачем нужна геолокация?','Только с вашего разрешения: чтобы определить примерный город для мест. Публичный поиск включается отдельно.',`<div class="notice">Точная координата не будет показана другим людям. Для сообщества требуется отдельное согласие; по умолчанию все переключатели приватны.</div><div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal">Не сейчас</button><button class="btn btn-primary" data-action="confirm-location">Разрешить определить город</button></div>`);modalRoot.querySelector('[data-action="confirm-location"]')?.addEventListener('click',()=>{closeModal();navigator.geolocation.getCurrentPosition(pos=>{const lat=Math.round(pos.coords.latitude*10)/10,lon=Math.round(pos.coords.longitude*10)/10;state.settings.locationApprox=`${lat}, ${lon}`;state.settings.locationGranted=true;save();notify('Получена примерная координата; город нужно указать вручную')},()=>notify('Разрешение не получено. Можно продолжить без геолокации.'),{maximumAge:600000,timeout:8000})},{once:true})}
  function exportData(){const safe={...state,settings:{...state.settings,locationApprox:undefined},exportedAt:new Date().toISOString(),note:'Локальный экспорт прототипа. Вложения файлов не включены.'};downloadBlob(new Blob([JSON.stringify(safe,null,2)],{type:'application/json'}),'lapka-data.json');notify('Экспорт подготовлен')}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeModal();if(e.key==='Tab'&&modal){const els=[...modalRoot.querySelectorAll('button,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  document.addEventListener('submit',e=>{if(e.target.id==='food-check-form'){e.preventDefault();showFoodResult(document.getElementById('food-search').value)}if(e.target.id==='template-form'){e.preventDefault();const value=document.getElementById('f-template-note').value.trim();if(value){state.foodEntries;const notes=JSON.parse(localStorage.getItem('lapka-notes')||'[]');notes.push({text:value,date:today});localStorage.setItem('lapka-notes',JSON.stringify(notes));notify('Заметка сохранена локально')}closeModal()}});
  function intro(){if(state.settings.onboardingDone)return;openModal('Добро пожаловать в Лапку','Профили питомцев, напоминания и заметки — под вашим контролем. Данные сейчас сохраняются только в этом браузере.',`<div class="notice"><b>Геолокация</b> выключена. Вы можете продолжить без неё. Точная GPS-точка не показывается другим людям.</div><div class="notice">Публичные аккаунты, защищённая синхронизация, ветеринарный чат и каталог мест требуют подключения сервера. Вымышленных пользователей в приложении нет.</div><div class="modal-footer"><button class="btn btn-secondary" data-action="intro-location">Сначала настроить геолокацию</button><button class="btn btn-primary" data-action="intro-continue">Продолжить без геолокации</button></div>`);modalRoot.querySelector('[data-action="intro-continue"]')?.addEventListener('click',()=>{state.settings.onboardingDone=true;save();closeModal();notify('Добро пожаловать в Лапку')},{once:true});modalRoot.querySelector('[data-action="intro-location"]')?.addEventListener('click',()=>{state.settings.onboardingDone=true;save();closeModal();requestLocation()},{once:true})}
  render();intro();
})();
